import { hasConsent as martechConsent } from './martech.js';

let consentedLoaded = false;

// Generated by stardust deploy/martech-scaffold.mjs: martech.js decides; re-run it.
// True on the production hosts, where the CMP gates each tag
// (its category in martech.js loadTags()) and anything else in consented.js runs ungated.
// Off production: ?consent=accept|decline, else ?martech=on.
function hasConsent() {
  return martechConsent();
}

/**
 * Loads consented scripts once consent is available.
 */
function loadConsented() {
  if (consentedLoaded) return;
  consentedLoaded = true;
  import('./consented.js');
}

/**
 * Notifies listeners of the current consent state and loads consented
 * scripts if consent has been granted.
 */
function onConsentUpdate() {
  const consented = hasConsent();
  window.dispatchEvent(new CustomEvent('consent.update', { detail: { consented } }));
  if (consented) {
    loadConsented();
  }
}

onConsentUpdate();
